mapper.select:
select ac.seq, ac.email, ac.nick_name, ac.name, ac.phone, ac.birth, ac.gender, ac.sign_type, ac.is_dropped as dropped, ac.dropped_out_date, ac.drop_reason, (select count(*) from account_design_register where account_seq = ac.seq and is_enabled) as registerCount, to_char(cast(ac.created_at at time zone 'kst' AS timestamp), 'YYYY-MM-DD HH24:MI:SS') as createdAt from account ac left join account_roles ar on ar.account_seq = ac.seq
ar.roles != 'ADMIN' AND ac.is_enabled
ORDER BY ac.seq DESC LIMIT #{pagination.endNum} OFFSET #{pagination.startNum}

select ac.seq, ac.email, ac.nick_name, ac.name, ac.phone, ac.birth, ac.gender, ac.sign_type, ac.is_dropped as dropped, ac.dropped_out_date, ac.drop_reason, (select count(*) from account_design_register where account_seq = ac.seq and is_enabled) as registerCount, to_char(cast(ac.created_at at time zone 'kst' AS timestamp), 'YYYY-MM-DD HH24:MI:SS') as createdAt from account ac left join account_roles ar on ar.account_seq = ac.seq
ar.roles = 'ADMIN' AND ac.is_enabled
ORDER BY ac.seq DESC LIMIT #{pagination.endNum} OFFSET #{pagination.startNum}

SELECT COUNT(rece.*) from account_recent_notification rece

    rece.is_enabled
    AND rece.account_seq = #{acSeq}

select rece.seq, rece.message, to_char(cast(rece.created_at at time zone 'kst' AS timestamp), 'YYYY-MM-DD HH24:MI:SS') as createdAt from account_recent_notification rece
rece.is_enabled AND rece.account_seq = #{acSeq}
ORDER BY rece.seq DESC LIMIT #{pagination.endNum} OFFSET #{pagination.startNum}

